cd /workspace && python3 - <<'EOF'
import json, sys
sys.path.insert(0,'/workspace/tmp')
import reference
from fuzz_fast import run_engine
LS=['leaf-spine',3,2]
def s(tasks, groups=None, caps=None, txs=None):
    return {'topology':LS,'caps':caps or [10]*5,'groups':groups or [[1,100],[1,100]],'tasks':tasks,
            'query':{'groups':[],'nodes':[],'tasks':[]},'transactions':txs or []}
# illegal initial config in the LAST session invalidates the whole request
req={'version':2,'sessions':[s([[0,0,1,0,0]]), s([[0,0,1,0,0]], groups=[[0,100],[1,100]])]}
print('whole-request invalid:', run_engine(req))
# 16 sessions
req={'version':2,'sessions':[s([[0,0,1,0,0]]) for _ in range(16)]}
out=run_engine(req); print('16 sessions ok:', len(out['sessions']))
# 17 sessions -> invalid (schema bound)
req={'version':2,'sessions':[s([[0,0,1,0,0]]) for _ in range(17)]}
print('17 sessions ->', run_engine(req))
# repeated query ids and empty queries
req={'version':2,'sessions':[s([[0,0,1,0,0]], txs=[{'revision':0,'edits':[],'query':{'groups':[0]*100,'nodes':[1]*50,'tasks':[0]*50}}])]}
out=run_engine(req); c=out['sessions'][0]['transactions'][0]['certificate']
print('repeated ids:', len(c['groups']), len(c['nodes']), len(c['tasks']))
EOF
